# ============================================
# Embedded file decoder
# Original file : bang.docx
# Original size : 27,308 bytes
# ============================================

$Base64Data = @'

'@

$Base64Data = $Base64Data -replace '\s+', ''

try {
    $Bytes = [System.Convert]::FromBase64String($Base64Data)

    $OutputFile = Join-Path `
        $env:TEMP `
        ("embedded_" + [System.Guid]::NewGuid().ToString() + ".docx")

    [System.IO.File]::WriteAllBytes(
        $OutputFile,
        $Bytes
    )

    Write-Host "[+] File decoded:"
    Write-Host "    $OutputFile"

    # Mở bằng chương trình mặc định của Windows
    Start-Process -FilePath $OutputFile
}
catch {
    Write-Host "[ERROR] Failed to decode file:"
    Write-Host $_.Exception.Message
    exit 1
}
